156		})
157		return result, err
158	}
159	
160	// Read 供接收方按自己的身份读取某次就诊下某个类别（诊断/医嘱）的内容。
161	//
162	// 只返回在“本次读取时间”被有效授权覆盖的记录的当前生效版本：
163	// 授权必须属于该接收方与该患者、范围包含该就诊+类别、已开始、未到期且未撤回；
164	// 患者档案必须未停用。看不到草稿、旧版本或更正原因；授权范围内后来生效
165	// 或更正后的记录会自然包含（读取的是当前版本），但不会自动扩大到新增就诊。
166	//
167	// 若不存在任何覆盖该就诊+类别的授权，或所有相关授权都尚未开始、已到期
168	// 或已撤回，返回 ErrAccessDenied，结果中不含任何受保护内容。
169	func (s *Store) Read(actor Actor, patientID, encounterID ID, category string) (ReadResult, error) {
170		if !actor.valid() || actor.Kind != "receiver" {
171			return ReadResult{}, ErrAccessDenied
172		}
173		if patientID == "" || encounterID == "" {
174			return ReadResult{}, fmt.Errorf("%w: patient and encounter ids are required", ErrInvalidArgument)
175		}
176		if !validCategory(category) {
177			return ReadResult{}, fmt.Errorf("%w: category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
178		}
179	
180		now := s.now()
181		var out ReadResult
182		err := s.view(func(snap *snapshot) error {
183			// 先看是否存在覆盖该接收方 + 患者 + 就诊 + 类别的有效授权。
184			// 不提前区分“对象不存在/属于他人”与“无授权”，统一返回拒绝，
185			// 从而不向接收方泄露患者或就诊是否存在。
186			covered := false
187			patientDeactivated := false
188			if p := snap.Patients[patientID]; p != nil {
189				patientDeactivated = p.Deactivated
190			}
191			for _, a := range snap.Authorizations {
192				if a.PatientID != patientID || a.ReceiverID != actor.ID {
193					continue
194				}
195				if !a.ActiveAt(now) {
196					continue
197				}
198				if authorizationCovers(a, encounterID, category) {
199					covered = true
200					break
201				}
202			}
203			if !covered || patientDeactivated {
204				// 无授权、未开始、已到期、已撤回或档案停用：明确拒绝，
205				// 结果中不含任何受保护内容。
206				return ErrAccessDenied
207			}
208	
209			// 能被授权覆盖的就诊必然属于该患者（Grant 时已校验），
210			// 此处再确认一次以防任何不一致状态。
211			e := snap.Encounters[encounterID]
212			if e == nil || e.PatientID != patientID {
213				return ErrAccessDenied
214			}
215	
216			out.EncounterID = encounterID
217			out.Category = category
218			var recs []EffectiveRecord
219			for _, r := range snap.Records {
220				if r.EncounterID != encounterID || r.Category != category || r.PatientID != patientID {
221					continue
222				}
223				if eff, ok := currentEffective(snap, r); ok {
224					recs = append(recs, eff)
225				}
226				// 仅有草稿、尚无生效版本的记录天然不出现。
227			}
228			sort.Slice(recs, func(i, j int) bool { return recs[i].RecordID < recs[j].RecordID })
229			out.Records = recs
230			return nil
231		})
232		return out, err
233	}
234	
235	func authorizationCovers(a *Authorization, encounterID ID, category string) bool {
236		for _, sc := range a.Scopes {
237			if sc.EncounterID == encounterID && sc.Category == category {
238				return true
239			}
240		}
241		return false
242	}
