32	func setupPatientEncounter(t *testing.T, s *Store) (ID, ID) {
33		t.Helper()
34		p, err := s.RegisterPatient(doc, "合成患者甲")
35		if err != nil {
36			t.Fatalf("register patient: %v", err)
37		}
38		e, err := s.AddEncounter(doc, p.ID, time.Time{})
39		if err != nil {
40			t.Fatalf("add encounter: %v", err)
41		}
42		return p.ID, e.ID
43	}
