52		m := map[string]int{}
53		for _, e := range events {
54			m[e.Action]++
55		}
56		return m
57	}
58	
59	// ---- 基线行为保留 ----
60	
61	func TestReadyStillTrue(t *testing.T) {
62		if !Ready() {
63			t.Fatal("Ready must remain true")
64		}
65	}
66	
67	// ---- 患者与就诊 ----
68	
69	func TestRegisterPatientIsSyntheticAndStableID(t *testing.T) {
70		s, _ := newTestStore(t)
71		p, err := s.RegisterPatient(doc, "合成患者甲")
72		if err != nil {
73			t.Fatalf("register: %v", err)
74		}
75		if p.ID == "" {
76			t.Fatal("patient id empty")
77		}
78		if p.Source != SyntheticSource {
79			t.Fatalf("source = %q, want %q", p.Source, SyntheticSource)
80		}
81		got, err := s.GetPatient(doc, p.ID)
82		if err != nil {
83			t.Fatalf("get: %v", err)
84		}
85		if got.ID != p.ID {
86			t.Fatalf("id not stable: %q vs %q", got.ID, p.ID)
87		}
