390			t.Fatalf("repeat revoke after deactivation added events: %d -> %d", nAfterRevoke, n)
391		}
392		// 接收方不能继续读取。
393		if _, err := s.Read(rcv, pid, eid, Order); !errors.Is(err, ErrAccessDenied) {
394			t.Fatalf("receiver read err = %v", err)
