406			t.Fatalf("records = %d, want 2", len(chart.Records))
407		}
408		if auditActions(chart.AuditEvents)[ActionDeactivated] != 1 {
409			t.Fatalf("deactivation audit missing: %+v", chart.AuditEvents)
410		}
411	}
