464	func TestReopenPreservesStateAndRecomputesExpiry(t *testing.T) {
465		dir := t.TempDir()
466		clk := &fakeClock{t: time.Date(2026, 3, 1, 8, 0, 0, 0, time.UTC)}
467		open := func() *Store {
