516		}
517		// 窗口内可读。
518		if res, err := s2.Read(rcv, p.ID, e.ID, Diagnosis); err != nil || len(res.Records) != 1 || res.Records[0].Content != "v2" {
519			t.Fatalf("read after reopen: %+v %v", res, err)
520		}
521		// 撤回后重开：撤回状态与撤回审计持久保留，接收方仍被拒绝。
522		if err := s2.Revoke(doc, p.ID, a.ID); err != nil {
