527		}
528	
529		s2b := open()
530		gotAuth2, err := s2b.GetAuthorization(doc, p.ID, a.ID)
531		if err != nil {
532			t.Fatalf("authorization lost after reopen: %v", err)
533		}
534		if gotAuth2.RevokedAt == nil {
535			t.Fatal("revocation not persisted across reopen")
536		}
537		if _, err := s2b.Read(rcv, p.ID, e.ID, Diagnosis); !errors.Is(err, ErrAccessDenied) {
538			t.Fatalf("revoked grant must deny after reopen: %v", err)
539		}
540		// 重开后重复撤回仍幂等。
541		rn1 := len(mustAudit(t, s2b, p.ID))
542		if err := s2b.Revoke(doc, p.ID, a.ID); err != nil {
543			t.Fatal(err)
544		}
545		if rn2 := len(mustAudit(t, s2b, p.ID)); rn2 != rn1 {
546			t.Fatalf("idempotent revoke after reopen added events: %d -> %d", rn1, rn2)
547		}
548		if err := s2b.Close(); err != nil {
549			t.Fatal(err)
550		}
551	
552		// 时间推进到授权到期之后再次打开：到期按本次读取时间判断。
553		clk.t = grantEnd.Add(time.Hour)
554		s3 := open()
