	if err != nil {
		t.Fatal(err)
	}
	if got.ID != x1.ID || len(got.Package.Records) != 1 {
		t.Fatalf("get exchange bad: %+v", got)
	}
	if _, err := f.s.GetExchange(doc, f.pid, "exch_missing"); !errors.Is(err, ErrNotFound) {
